def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    airplanes = image_patch.find("airplane")
    runways = image_patch.find("runway")

    if not airplanes or not runways:
        return image_patch

    airplane_runway_pairs = []
    for airplane in airplanes:
        for runway in runways:
            if is_on(runway, airplane):
                airplane_runway_pairs.append((airplane, runway))

    if not airplane_runway_pairs:
