    closest_pair = min(airplane_runway_pairs, key=lambda pair: distance(pair[0], pair[1]))
    return closest_pair[0]


def is_on(runway: ImagePatch, airplane: ImagePatch) -> bool:
    runway_center_x = (runway.left + runway.right) / 2
    runway_center_y = (runway.lower + runway.upper) / 2
    airplane_center_x = (airplane.left + airplane.right) / 2
    airplane_center_y = (airplane.lower + airplane.upper) / 2

    return abs(runway_center_x - airplane_center_x) < 100 and abs(runway_center_y - airplane_center_y) < 100

